const compareVersions = (a, b) => {
  const aSplit = a.split(".");
  const bSplit = b.split(".");

  const aMajor = parseInt(aSplit[0]);
  const aMinor = parseInt(aSplit[1]);
  const aPatch = parseInt(aSplit[2]);

  const bMajor = parseInt(bSplit[0]);
  const bMinor = parseInt(bSplit[1]);
  const bPatch = parseInt(bSplit[2]);

  if (aMajor > bMajor) {
    return 1;
  } else if (aMajor < bMajor) {
    return -1;
  } else {
    if (aMinor > bMinor) {
      return 1;
    } else if (aMinor < bMinor) {
      return -1;
    } else {
      if (aPatch > bPatch) {
        return 1;
      } else if (aPatch < bPatch) {
        return -1;
      } else {
        return 0;
      }
    }  
  }
};

const aggregated = {};
const displayOrder = [];

for(const d of data) {
  if(aggregated[d.program] === undefined) {
    aggregated[d.program] = {};
  }

  if(aggregated[d.program][d.version] === undefined) {
    aggregated[d.program][d.version] = [];
  } 

  aggregated[d.program][d.version].push(d);

  if(!displayOrder.includes(`${d.program}-${d.version}`)) {
    displayOrder.push(`${d.program}-${d.version}`);
  }
}

//return aggregated;

return displayOrder.map(d => {
  const ds = d.split("-");
  const firmwareTargets = aggregated[ds[0]][ds[1]];

  return {
    program: ds[0],
    version: ds[1],
    targets: firmwareTargets.map(ft => ft.target),
  };
});
